// FILE: frontend/src/LogDetail.js
//
// --- VERSION 1.1.0 CHANGE ---
// - This component is now a fully dynamic charting tool.
// - It fetches all available PIDs (columns) for a log and displays them as checkboxes.
// - Users can select any combination of PIDs to visualize on the chart.
// - The chart instantly re-renders when the selection changes.
// - A predefined, high-contrast color palette is used to ensure chart lines are distinct.
// -----------------------------

import React, { useState, useEffect, useMemo } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

// A palette of high-contrast colors for the chart lines
const CHART_COLORS = [
  '#38BDF8', // sky-400
  '#F59E0B', // amber-500
  '#4ADE80', // green-400
  '#F472B6', // pink-400
  '#A78BFA', // violet-400
  '#2DD4BF', // teal-400
  '#FB7185', // rose-400
  '#FACC15', // yellow-400
];

function LogDetail() {
  const { logId } = useParams();
  const [logData, setLogData] = useState([]);
  const [availablePIDs, setAvailablePIDs] = useState([]);
  const [selectedPIDs, setSelectedPIDs] = useState(new Set(['vehicle_speed', 'engine_rpm']));
  const [status, setStatus] = useState('Loading log data...');
  const [logFileName, setLogFileName] = useState('');

  useEffect(() => {
	const fetchLogData = async () => {
	  try {
		const logInfoResponse = await axios.get('http://localhost:5001/api/logs');
		const currentLog = logInfoResponse.data.find(log => log.log_id === parseInt(logId));
		if (currentLog) {
			setLogFileName(currentLog.file_name);
		}

		const response = await axios.get(`http://localhost:5001/api/logs/${logId}/data`);
		const { data, columns } = response.data;

		if (data && data.length > 0) {
		  setLogData(data);
		  // Exclude 'timestamp' from the list of selectable PIDs
		  setAvailablePIDs(columns.filter(c => c !== 'timestamp'));
		} else {
		  setStatus('No data rows found for this log.');
		}

	  } catch (error) {
		console.error("Error fetching log detail:", error);
		setStatus('Failed to load log data.');
	  }
	};

	fetchLogData();
  }, [logId]);

  const handlePIDSelectionChange = (pid) => {
	setSelectedPIDs(prevSelected => {
	  const newSelected = new Set(prevSelected);
	  if (newSelected.has(pid)) {
		newSelected.delete(pid);
	  } else {
		newSelected.add(pid);
	  }
	  return newSelected;
	});
  };

  const chartData = useMemo(() => {
	if (!logData || logData.length === 0) return null;

	const labels = logData.map(row => new Date(row.timestamp * 1000).toLocaleTimeString());

	return {
	  labels,
	  datasets: Array.from(selectedPIDs).map((pid, index) => ({
		label: pid.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()), // Prettify label
		data: logData.map(row => row[pid]),
		borderColor: CHART_COLORS[index % CHART_COLORS.length],
		backgroundColor: `${CHART_COLORS[index % CHART_COLORS.length]}80`, // Add alpha for fill
		yAxisID: `y${index}`,
		tension: 0.1,
		pointRadius: 1,
		borderWidth: 2,
	  })),
	};
  }, [logData, selectedPIDs]);

  const chartOptions = useMemo(() => {
	const scales = {
		x: { ticks: { color: '#9CA3AF' } }
	};

	Array.from(selectedPIDs).forEach((pid, index) => {
		scales[`y${index}`] = {
			type: 'linear',
			display: true,
			position: index % 2 === 0 ? 'left' : 'right',
			title: {
				display: true,
				text: pid.replace(/_/g, ' '),
				color: CHART_COLORS[index % CHART_COLORS.length],
			},
			ticks: { color: CHART_COLORS[index % CHART_COLORS.length] },
			grid: {
				drawOnChartArea: index === 0, // Only draw grid for the first Y-axis
			},
		};
	});

	return {
		responsive: true,
		maintainAspectRatio: false,
		interaction: { mode: 'index', intersect: false },
		plugins: {
			title: { display: true, text: `Trip Data for: ${logFileName}`, color: '#FFFFFF', font: { size: 18 } },
			legend: { display: false } // Legend is redundant with the checkboxes
		},
		scales: scales,
	};
  }, [selectedPIDs, logFileName]);


  return (
	<div className="grid grid-cols-1 md:grid-cols-4 gap-6">
	  {/* Chart Area */}
	  <div className="md:col-span-3 bg-gray-800 rounded-lg shadow-xl p-4 h-[70vh]">
		{chartData ? (
		  <Line options={chartOptions} data={chartData} />
		) : (
		  <p className="flex items-center justify-center h-full text-gray-400">{status}</p>
		)}
	  </div>

	  {/* PID Selector */}
	  <div className="md:col-span-1 bg-gray-800 rounded-lg shadow-xl p-4">
		<h3 className="text-lg font-bold border-b-2 border-cyan-500 pb-2 mb-3">Select PIDs to Display</h3>
		<div className="flex flex-col space-y-2 max-h-[65vh] overflow-y-auto">
		  {availablePIDs.map(pid => (
			<label key={pid} className="flex items-center space-x-3 cursor-pointer p-2 rounded-md hover:bg-gray-700">
			  <input
				type="checkbox"
				className="h-4 w-4 rounded bg-gray-600 border-gray-500 text-cyan-500 focus:ring-cyan-600"
				checked={selectedPIDs.has(pid)}
				onChange={() => handlePIDSelectionChange(pid)}
			  />
			  <span className="text-sm capitalize">{pid.replace(/_/g, ' ')}</span>
			</label>
		  ))}
		</div>
	  </div>
	</div>
  );
}

export default LogDetail;
